ia['file_name']) ?></option><?php endforeach ?></select><small><?= $adminText('admin.pages.social_image_help','The selected image is used in social media previews.') ?></small></label><div class="media-options"><button class="button" type="submit"><?= $adminText('admin.common.save','Save') ?></button><button class="button secondary" type="button" id="page-preview-button"><?= $adminText('admin.pages.open_preview','Open preview') ?></button><small id="autosave-status" aria-live="polite"></small></div></form><?php if($pageAutosave): ?><section class="content-admin"><p><?= $adminText('admin.pages.autosave_found','An unsaved automatic draft was found:') ?> <?= $h($pageAutosave['saved_at']) ?></p><button type="button" class="button secondary" id="restore-autosave"><?= $adminText('admin.pages.restore_autosave','Restore automatic draft') ?></button></section><?php endif ?></section><?php if($ep && !$pending): ?><section class="content-admin"><h2><?= $adminText('admin.pages.revision_history','Revision history') ?></h2><?php if($compareRevision): ?><h3><?= $adminText('admin.pages.revision_compare','Compare revisions') ?></h3><div class="media-options"><div><strong><?= $adminText('admin.pages.selected_revision','Selected previous version') ?> · <?= $h($compareRevision['created_at']) ?></strong><pre class="revision-preview"><?= $h(html_entity_decode((string)($compareRevision['body']??''),ENT_QUOTES|ENT_HTML5,'UTF-8')) ?></pre></div><div><strong><?= $adminText('admin.pages.current_revision','Current saved version') ?></strong><pre class="revision-preview"><?= $h(html_entity_decode((string)($ep['body']??''),ENT_QUOTES|ENT_HTML5,'UTF-8')) ?></pre></div></div><?php endif ?><?php if(!$pageRevisions): ?><p><?= $adminText('admin.pages.no_revisions','No revisions saved yet. Previous versions will appear here after the first change.') ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= $adminText('admin.common.date','Date') ?></th><th><?= $adminText('admin.pages.title','Title') ?></th><th><?= $adminText('admin.pages.status','Status') ?></th><th><?= $adminText('admin.common.actions','Actions') ?></th></tr></thead><tbody><?php foreach($pageRevisions as $revision): ?><tr><td><?= $h($revision['created_at']) ?></td><td><?= $h($revision['title']) ?></td><td><?= $h($revision['status']) ?></td><td><a href="<?= $h(CoreCMS\Core\Url::to('/admin/?section=pages&edit_page='.(int)$ep['id'].'&compare_revision='.(int)$revision['id'])) ?>">Karşılaştır</a> · <form method="post" class="inline-form" onsubmit="return confirm('Bu sürüm geri yüklensin mi? Mevcut içerik de geçmişe kaydedilecek.')"><?= CoreCMS\Core\Csrf::field() ?><input type="hidden" name="action" value="page_revision_restore"><input type="hidden" name="revision_id" value="<?= $h($revision['id']) ?>"><button class="link-button">Bu sürümü geri yükle</button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endif ?>
